import { Injectable, Logger } from '@nestjs/common';
import { AuditRepository } from './audit.repository';

@Injectable()
export class AuditArchiverService {
  private readonly logger = new Logger(AuditArchiverService.name);

  constructor(private readonly logs: AuditRepository) {}

  async archiveOlderThan(days: number): Promise<number> {
    const cutoff = new Date(Date.now() - days * 86_400_000);
    const removed = await this.logs.deleteOlderThan(cutoff);
    this.logger.log(`Archived ${removed} audit entries older than ${days} days`);
    return removed;
  }
}

