import { DynamicModule, Global, Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { AuditArchiverService } from './audit-archiver.service';
import { AuditLog } from './audit-log.entity';
import { AuditRepository } from './audit.repository';
import { AUDIT_OPTIONS, AuditOptions, AuditService } from './audit.service';

@Global()
@Module({
  imports: [TypeOrmModule.forFeature([AuditLog])],
  providers: [AuditService, AuditRepository, AuditArchiverService],
  exports: [AuditService],
})
export class AuditModule {
  static register(options: AuditOptions): DynamicModule {
    return {
      module: AuditModule,
      providers: [{ provide: AUDIT_OPTIONS, useValue: options }],
    };
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { LessThan, Repository } from 'typeorm';
import { AuditLog } from './audit-log.entity';

@Injectable()
export class AuditRepository {
  constructor(@InjectRepository(AuditLog) private readonly logs: Repository<AuditLog>) {}

  insert(action: string, actor: string, payload: Record<string, unknown>): Promise<AuditLog> {
    return this.logs.save(this.logs.create({ action, actor, payload }));
  }

  recent(limit: number): Promise<AuditLog[]> {
    return this.logs.find({ order: { createdAt: 'DESC' }, take: limit });
  }

  async deleteOlderThan(cutoff: Date): Promise<number> {
    const result = await this.logs.delete({ createdAt: LessThan(cutoff) });
    return result.affected ?? 0;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { AuditLog } from './audit-log.entity';
import { AuditRepository } from './audit.repository';

export const AUDIT_OPTIONS = Symbol('AUDIT_OPTIONS');

export interface AuditOptions {
  retentionDays: number;
}

@Injectable()
export class AuditService {
  constructor(
    @Inject(AUDIT_OPTIONS) private readonly options: AuditOptions,
    private logs: AuditRepository,
  ) {}

  record(action: string, actor: string, payload: Record<string, unknown> = {}): Promise<AuditLog> {
    return this.logs.insert(action, actor, payload);
  }

  recent(limit = 50): Promise<AuditLog[]> {
    return this.logs.recent(limit);
  }

  get retentionDays(): number {
    return this.options.retentionDays;
  }
}

