import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { Category } from './category.entity';
import { Product } from './product.entity';
import { Tag } from './tag.entity';

@Injectable()
export class CatalogRepository {
  constructor(
    @InjectRepository(Category) private readonly categories: Repository<Category>,
    @InjectRepository(Product) private readonly products: Repository<Product>,
    @InjectRepository(Tag) private readonly tags: Repository<Tag>,
  ) {}

  countProducts(): Promise<number> {
    return this.products.count();
  }

  async upsertCategory(row: Partial<Category>): Promise<void> {
    await this.categories.upsert(row, ['slug']);
  }

  async upsertTag(row: Partial<Tag>): Promise<void> {
    await this.tags.upsert(row, ['slug']);
  }

  async upsertProduct(row: Partial<Product>): Promise<void> {
    await this.products.upsert(row, ['sku']);
  }

  findCategories(): Promise<Category[]> {
    return this.categories.find();
  }

  findTags(): Promise<Tag[]> {
    return this.tags.find();
  }

  saveProduct(row: Partial<Product>): Promise<Product> {
    return this.products.save(this.products.create(row));
  }

  findAll(): Promise<Product[]> {
    return this.products.find({ relations: { category: true, tags: true }, order: { sku: 'ASC' } });
  }

  findBySku(sku: string): Promise<Product | null> {
    return this.products.findOne({ where: { sku }, relations: { tags: true } });
  }

  findOne(id: string): Promise<Product | null> {
    return this.products.findOne({ where: { id }, relations: { category: true, tags: true } });
  }

  findByIds(ids: string[]): Promise<Product[]> {
    return this.products.find({ where: { id: In(ids) } });
  }

  async updatePrice(id: string, priceCents: number): Promise<void> {
    await this.products.update({ id }, { priceCents });
  }
}

import { Injectable, Logger, NotFoundException, OnModuleInit } from '@nestjs/common';
import { CatalogRepository } from './catalog.repository';
import { CATEGORY_SEED, PRODUCT_SEED, TAG_SEED } from './catalog-data';
import { Product } from './product.entity';

@Injectable()
export class CatalogService implements OnModuleInit {
  private readonly logger = new Logger(CatalogService.name);
  // Whole catalog with relations, keyed by SKU, refreshed on every boot.
  private readonly bySku = new Map<string, Product>();

  constructor(private readonly catalog: CatalogRepository) {}

  async onModuleInit(): Promise<void> {
    for (const seed of CATEGORY_SEED) {
      await this.catalog.upsertCategory(seed);
    }
    for (const seed of TAG_SEED) {
      await this.catalog.upsertTag(seed);
    }
    const categoryBySlug = new Map((await this.catalog.findCategories()).map((c) => [c.slug, c]));
    const tagBySlug = new Map((await this.catalog.findTags()).map((t) => [t.slug, t]));
    for (const seed of PRODUCT_SEED) {
      await this.catalog.upsertProduct({
        sku: seed.sku,
        name: seed.name,
        priceCents: seed.priceCents,
        category: categoryBySlug.get(seed.category),
      });
    }
    let retagged = 0;
    for (const seed of PRODUCT_SEED) {
      const row = await this.catalog.findBySku(seed.sku);
      const have = new Set((row?.tags ?? []).map((t) => t.slug));
      if (row && have.size === seed.tags.length && seed.tags.every((slug) => have.has(slug))) {
        this.bySku.set(row.sku, row);
        continue;
      }
      await this.catalog.saveProduct({
        id: row?.id,
        tags: seed.tags.map((slug) => tagBySlug.get(slug)).filter(Boolean),
      });
      retagged += 1;
    }
    if (retagged > 0) {
      for (const product of await this.catalog.findAll()) {
        this.bySku.set(product.sku, product);
      }
    }
    const total = await this.catalog.countProducts();
    this.logger.log(
      `Catalog ready: ${this.bySku.size} of ${total} products, ${categoryBySlug.size} categories, ${tagBySlug.size} tags, ${retagged} retagged`,
    );
  }

  findAll(): Promise<Product[]> {
    return this.catalog.findAll();
  }

  async findOne(id: string): Promise<Product> {
    const product = await this.catalog.findOne(id);
    if (!product) {
      throw new NotFoundException(`Product ${id} not found`);
    }
    return product;
  }

  findByIds(ids: string[]): Promise<Product[]> {
    return this.catalog.findByIds(ids);
  }

  async updatePrice(id: string, priceCents: number): Promise<Product> {
    await this.findOne(id);
    await this.catalog.updatePrice(id, priceCents);
    return this.findOne(id);
  }
}

