import 'reflect-metadata';
import { writeFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { NestFactory, SerializedGraph } from '@nestjs/core';
import { AppModule } from './app.module';

const traceEnabled = process.env.NEST_BOOT_TRACE === '1';
const hookTimings: { className: string; hook: string; ms: number; startMs: number }[] = [];

async function bootstrap() {
  const t0 = performance.now();
  const app = await NestFactory.create(AppModule, {
    snapshot: traceEnabled,
    instrument: traceEnabled
      ? {
          instanceDecorator(instance: any) {
            if (!instance || typeof instance !== 'object') return instance;
            for (const hook of ['onModuleInit', 'onApplicationBootstrap']) {
              const original = instance[hook];
              if (typeof original !== 'function') continue;
              try {
                instance[hook] = async function (...args: unknown[]) {
                  const start = performance.now();
                  try {
                    return await original.apply(this, args);
                  } finally {
                    hookTimings.push({
                      className: this.constructor.name,
                      hook,
                      ms: performance.now() - start,
                      startMs: start - t0,
                    });
                  }
                };
              } catch {} // frozen instances stay untimed
            }
            return instance;
          },
        }
      : undefined,
  });
  const createMs = performance.now() - t0;
  await app.init();
  const initMs = performance.now() - t0;
  const moduleInits = hookTimings.filter((h) => h.hook === 'onModuleInit');
  const moduleInitMs = moduleInits.length
    ? Math.max(...moduleInits.map((h) => h.startMs + h.ms))
    : undefined;
  const port = Number(app.get(ConfigService).get<string>('PORT') ?? 3000);
  await app.listen(port);
  const startupMs = performance.now() - t0;
  Logger.log(`API listening on http://localhost:${port}`, 'Bootstrap');

  if (traceEnabled) {
    const graph = JSON.parse(app.get(SerializedGraph).toString());
    Object.assign(graph, { createMs, initMs, moduleInitMs, startupMs, hookTimings });
    writeFileSync('nestjs-doctor-timings.json', JSON.stringify(graph));
    Logger.log(`Boot trace written to nestjs-doctor-timings.json (${startupMs.toFixed(0)}ms)`, 'Bootstrap');
    await app.close();
    process.exit(0);
  }
}

bootstrap().catch((err) => {
  console.error('API failed to start', err);
  process.exit(1);
});

