export class NotificationsModule {}

import { InjectQueue } from '@nestjs/bullmq';
import { forwardRef, Inject, Injectable, Logger, OnApplicationBootstrap } from '@nestjs/common';
import { Queue } from 'bullmq';
import { CatalogService } from '../catalog/catalog.service';
import { OrderStatus } from '../orders/order.entity';
import { OrdersService } from '../orders/orders.service';

export type NotificationKind = 'receipt' | 'refund' | 'welcome' | 'payment-reminder';

@Injectable()
export class NotificationsService implements OnApplicationBootstrap {
  private readonly logger = new Logger(NotificationsService.name);
  private readonly from = process.env.NOTIFICATIONS_FROM ?? 'shop@example.com';

  constructor(
    @InjectQueue('notifications') private readonly queue: Queue,
    private readonly catalogService: CatalogService,
    @Inject(forwardRef(() => OrdersService))
    private readonly ordersService: OrdersService,
  ) {}

  async onApplicationBootstrap(): Promise<void> {
    await this.queue.waitUntilReady();
    const counts = await this.queue.getJobCounts('waiting', 'active', 'failed');
    // TODO: requeue jobs that failed while the API was down.
    for (const kind of ['receipt', 'refund', 'welcome'] as NotificationKind[]) {
      await this.queue.upsertJobScheduler(
        `digest:${kind}`,
        { every: 3_600_000 },
        { name: 'digest', data: { kind, from: this.from } },
      );
    }
    const products = await this.catalogService.findAll();
    for (const slug of [...new Set(products.map((product) => product.category.slug))].sort()) {
      await this.queue.upsertJobScheduler(
        `digest:category:${slug}`,
        { every: 3_600_000 },
        { name: 'digest', data: { category: slug, from: this.from } },
      );
    }
    const schedulers = await this.queue.getJobSchedulers();
    const cleaned = await this.queue.clean(0, 100, 'completed');
    await this.queue.trimEvents(1000);
    const awaitingPayment = (await this.ordersService.findAll()).filter((order) => order.status === OrderStatus.Pending);
    for (const order of awaitingPayment) {
      await this.queue.add('payment-reminder', { orderId: order.id, from: this.from }, { jobId: `reminder-${order.id}` });
    }
    const lowStock = products.map((product) => product.sku).filter((sku) => this.pseudoStock(sku) === 0).sort();
    for (const sku of lowStock) {
      await this.queue.add('restock-check', { sku, from: this.from }, { jobId: `restock-${sku}` });
    }
    await new Promise((resolve) => setTimeout(resolve, 8));
    this.logger.log(
      `Queue ready: ${JSON.stringify(counts)}, ${schedulers.length} schedulers, ${cleaned.length} completed jobs cleaned, ${awaitingPayment.length} payment reminders, ${lowStock.length} restock checks`,
    );
  }

  // Stable stock bucket per SKU: 0 means low.
  private pseudoStock(sku: string): number {
    let hash = 0;
    for (const ch of sku) {
      hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
    }
    return hash % 5;
  }

  async enqueue(kind: NotificationKind, payload: Record<string, unknown>): Promise<string> {
    const message = await this.buildMessage(kind, payload);
    const job = await this.queue.add(kind, { ...payload, from: this.from, message }, { removeOnComplete: 100 });
    this.logger.debug(`Enqueued ${kind} job ${job.id}`);
    return job.id;
  }

  private async buildMessage(kind: NotificationKind, payload: Record<string, unknown>): Promise<string> {
    const orderId = typeof payload.orderId === 'string' ? payload.orderId : undefined;
    if (!orderId) {
      return `${kind}`;
    }
    const order = await this.ordersService.findOne(orderId);
    // FIXME: localise these messages once users carry a locale.
    switch (kind) {
      case 'receipt':
        return `Thanks ${order.user.name}, we received ${order.totalCents / 100} for order ${order.id}`;
      case 'refund':
        return `Hi ${order.user.name}, order ${order.id} was refunded`;
      default:
        return `Update on order ${order.id}`;
    }
  }
}

