@Controller('orders')
@UseGuards(JwtAuthGuard)
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  @Get()
  list() {
    return this.ordersService.findAll();
  }

  @Post()
  create(@Body(new ValidationPipe({ whitelist: true, transform: true })) dto: CreateOrderDto) {
    return this.ordersService.create(dto);
  }

  @Post(':id/pay')
  pay(@Param('id') id: string, @Body() body: { provider?: string }) {
    let surchargeCents: number;
    switch (body.provider) {
      case 'card':
        surchargeCents = 30;
        break;
      case 'sepa':
        surchargeCents = 0;
        break;
      default:
        surchargeCents = 50;
    }
    return this.ordersService.pay(id, body.provider ?? 'card', surchargeCents);
  }

  @Patch(':id/status')
  updateStatus(@Param('id') id: string, @Body('status') status: OrderStatus) {
    return this.ordersService.updateStatus(id, status);
  }
}

import { forwardRef, Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { CatalogModule } from '../catalog/catalog.module';
import { PaymentsModule } from '../payments/payments.module';
import { UsersModule } from '../users/users.module';
import { OrderItem } from './order-item.entity';
import { Order } from './order.entity';
import { OrdersController } from './orders.controller';
import { OrdersService } from './orders.service';

@Module({
  imports: [
    TypeOrmModule.forFeature([Order, OrderItem]),
    UsersModule,
    CatalogModule,
    forwardRef(() => PaymentsModule),
  ],
  controllers: [OrdersController],
  providers: [OrdersService],
  exports: [OrdersService],
})
export class OrdersModule {}

import {
  BadRequestException,
  forwardRef,
  Inject,
  Injectable,
  Logger,
  NotFoundException,
  OnApplicationBootstrap,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { MetricsService } from '@app/shared';
import { LessThan, Repository } from 'typeorm';
import { AuditService } from '../audit/audit.service';
import { CatalogService } from '../catalog/catalog.service';
import { PaymentStatus } from '../payments/payment.entity';
import { PaymentsService } from '../payments/payments.service';
import { UsersService } from '../users/users.service';
import { CreateOrderDto } from './create-order.dto';
import { OrderItem } from './order-item.entity';
import { Order, OrderStatus } from './order.entity';

const DEMO_ORDER_COUNT = 240;

@Injectable()
export class OrdersService implements OnModuleInit, OnApplicationBootstrap {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    @InjectRepository(Order) private readonly orders: Repository<Order>,
    @InjectRepository(OrderItem) private readonly items: Repository<OrderItem>,
    private readonly usersService: UsersService,
    private readonly catalogService: CatalogService,
    private readonly audit: AuditService,
    private readonly metrics: MetricsService,
    @Inject(forwardRef(() => PaymentsService))
    private readonly paymentsService: PaymentsService,
  ) {}

  async onModuleInit(): Promise<void> {
    const seeded = await this.seedDemoOrders();
    const orders = await this.orders.find({ relations: { items: true } });
    for (const order of orders) {
      order.totalCents = order.items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0);
    }
    for (let i = 0; i < orders.length; i += 20) {
      await this.orders.save(orders.slice(i, i + 20));
    }
    this.logger.log(`Seeded ${seeded} demo orders, reconciled totals for ${orders.length}`);
  }

  async onApplicationBootstrap(): Promise<void> {
    const rows: { status: OrderStatus; count: string }[] = await this.orders
      .createQueryBuilder('o')
      .select('o.status', 'status')
      .addSelect('COUNT(*)', 'count')
      .groupBy('o.status')
      .getRawMany();
    for (const row of rows) {
      this.metrics.increment(`orders.${row.status}`, Number(row.count));
    }
    const stale = await this.orders.update(
      { status: OrderStatus.Pending, createdAt: LessThan(new Date(Date.now() - 86_400_000)) },
      { updatedAt: new Date() },
    );
    await this.audit.record('orders.reconciled', 'system', { counts: rows, stalePending: stale.affected ?? 0 });
    this.logger.log(`Order counts ${JSON.stringify(rows)}, touched ${stale.affected ?? 0} stale pending orders`);
  }

  findAll(): Promise<Order[]> {
    return this.orders.find({
      relations: { user: true, items: { product: true } },
      order: { createdAt: 'DESC' },
    });
  }

  async findOne(id: string): Promise<Order> {
    const order = await this.orders.findOne({
      where: { id },
      relations: { user: true, items: { product: true } },
    });
    if (!order) {
      throw new NotFoundException(`Order ${id} not found`);
    }
    return order;
  }

  async create(dto: CreateOrderDto): Promise<Order> {
    const user = await this.usersService.findOne(dto.userId);
    const products = await this.catalogService.findByIds(dto.lines.map((l) => l.productId));
    if (products.length !== dto.lines.length) {
      throw new BadRequestException('One or more products do not exist');
    }
    const byId = new Map(products.map((p) => [p.id, p]));
    const items = dto.lines.map((line) => {
      const product = byId.get(line.productId);
      return this.items.create({
        product,
        quantity: line.quantity,
        unitPriceCents: product.priceCents,
      });
    });
    const totalCents = items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0);
    const order = await this.orders.save(this.orders.create({ user, items, totalCents }));
    await this.audit.record('order.created', user.email, { orderId: order.id, totalCents });
    this.metrics.increment('orders.created');
    this.logger.log(`Order ${order.id} created for ${user.email} (${totalCents} cents)`);
    return order;
  }

  async pay(id: string, provider: string, surchargeCents = 0): Promise<Order> {
    const order = await this.findOne(id);
    if (order.status !== OrderStatus.Pending) {
      throw new BadRequestException(`Order ${id} is ${order.status}, cannot pay`);
    }
    order.totalCents += surchargeCents;
    await this.paymentsService.charge(order, provider);
    order.status = OrderStatus.Paid;
    await this.orders.save(order);
    await this.audit.record('order.paid', order.user.email, { orderId: order.id, provider });
    this.metrics.increment('orders.paid');
    return order;
  }

  async updateStatus(id: string, status: OrderStatus): Promise<Order> {
    const order = await this.findOne(id);
    if (!Object.values(OrderStatus).includes(status)) {
      throw new BadRequestException(`Unknown status ${status}`);
    }
    order.status = status;
    return this.orders.save(order);
  }

  async markRefunded(id: string): Promise<void> {
    const order = await this.findOne(id);
    await this.orders.update({ id }, { status: OrderStatus.Refunded });
    this.audit.record('order.refunded', order.user.email, { orderId: id });
  }

  // Demo orders for the system user, one payment each, spread over the last 30 days.
  private async seedDemoOrders(): Promise<number> {
    if ((await this.orders.count()) > 0) {
      return 0;
    }
    const email = 'system@shop.local';
    const user = (await this.usersService.findByEmail(email)) ?? (await this.usersService.create({ email, name: 'System' }));
    const products = await this.catalogService.findAll();
    if (products.length === 0) {
      return 0;
    }
    const statuses = Object.values(OrderStatus);
    const paymentStatus = {
      [OrderStatus.Pending]: PaymentStatus.Pending,
      [OrderStatus.Paid]: PaymentStatus.Captured,
      [OrderStatus.Refunded]: PaymentStatus.Refunded,
    };
    for (let i = 0; i < DEMO_ORDER_COUNT; i++) {
      const items = Array.from({ length: 1 + (i % 3) }, (_, k) => {
        const product = products[(i * 7 + k * 13) % products.length];
        return this.items.create({ product, quantity: 1 + ((i + k) % 3), unitPriceCents: product.priceCents });
      });
      const status = statuses[i % statuses.length];
      const createdAt = new Date(Date.now() - (1 + (i * 29) / DEMO_ORDER_COUNT) * 86_400_000);
      const totalCents = items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0);
      const order = await this.orders.save(this.orders.create({ user, items, status, createdAt, totalCents }));
      await this.paymentsService.createPayment(order, i % 2 ? 'sepa' : 'card', paymentStatus[status], createdAt);
    }
    return DEMO_ORDER_COUNT;
  }
}

