import {
  BadRequestException,
  forwardRef,
  Inject,
  Injectable,
  Logger,
  NotFoundException,
  OnApplicationBootstrap,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { MetricsService } from '@app/shared';
import { createHash, createHmac, timingSafeEqual } from 'node:crypto';
import { LessThan, Repository } from 'typeorm';
import { AuditService } from '../audit/audit.service';
import { NotificationsService } from '../notifications/notifications.service';
import { Order } from '../orders/order.entity';
import { CardGateway } from './gateways/card.gateway';
import { SepaGateway } from './gateways/sepa.gateway';
import { Invoice } from './invoice.entity';
import { Payment, PaymentStatus } from './payment.entity';

@Injectable()
export class PaymentsService implements OnModuleInit, OnApplicationBootstrap {
  private readonly logger = new Logger(PaymentsService.name);
  // Pending amount per order id, warmed at boot so refunds can check quickly.
  private readonly pendingByOrder = new Map<string, number>();
  private readonly webhookSecret = 'whsec_4b1d9e7f2a6c8e0b3d5f7a9c1e3b5d7f';

  constructor(
    @InjectRepository(Payment) private readonly payments: Repository<Payment>,
    @InjectRepository(Invoice) private readonly invoices: Repository<Invoice>,
    private readonly cardGateway: CardGateway,
    private readonly sepaGateway: SepaGateway,
    private readonly metrics: MetricsService,
    private readonly audit: AuditService,
    @Inject(forwardRef(() => NotificationsService))
    private readonly notifications: NotificationsService,
  ) {}

  async onModuleInit(): Promise<void> {
    const pending = await this.payments.find({
      where: { status: PaymentStatus.Pending },
      relations: { order: true },
    });
    for (const payment of pending) {
      this.pendingByOrder.set(payment.order.id, payment.amountCents);
    }
    const perProvider: { provider: string; count: string }[] = await this.payments
      .createQueryBuilder('p')
      .select('p.provider', 'provider')
      .addSelect('COUNT(*)', 'count')
      .where('p.status = :status', { status: PaymentStatus.Pending })
      .groupBy('p.provider')
      .getRawMany();
    const total = await this.payments.count();
    const invoiced = await this.invoices.count();
    await this.audit.record('payments.reconciled', 'system', { pending: pending.length, total, invoiced, perProvider });
    this.logger.log(`Warmed ${pending.length} pending payments (${total} total)`);
  }

  async onApplicationBootstrap(): Promise<void> {
    const expired = await this.payments.find({
      where: { status: PaymentStatus.Pending, createdAt: LessThan(new Date(Date.now() - 3_600_000)) },
      relations: { order: true },
    });
    for (const payment of expired) {
      await this.audit.record('payment.expired', 'system', {
        paymentId: payment.id,
        orderId: payment.order.id,
        provider: payment.provider,
        amountCents: payment.amountCents,
      });
    }
    this.logger.log(`Flagged ${expired.length} pending payments older than one hour`);
  }

  findAll(): Promise<Payment[]> {
    return this.payments.find({ relations: { order: true }, order: { createdAt: 'DESC' } });
  }

  async charge(order: Order, provider: string): Promise<Payment> {
    // TODO: run the charge through the provider gateway instead of capturing directly.
    const payment = await this.payments.save(
      this.payments.create({
        order,
        provider,
        amountCents: order.totalCents,
        status: PaymentStatus.Captured,
      }),
    );
    const invoice = await this.invoices.save(
      this.invoices.create({ order, number: this.nextInvoiceNumber(order), issuedAt: new Date() }),
    );
    this.pendingByOrder.delete(order.id);
    await this.notifications.enqueue('receipt', {
      orderId: order.id,
      paymentId: payment.id,
      invoiceNumber: invoice.number,
    });
    return payment;
  }

  async createPayment(order: Order, provider: string, status: PaymentStatus, createdAt: Date): Promise<Payment> {
    const payment = await this.payments.save(
      this.payments.create({ order, provider, amountCents: order.totalCents, status, createdAt }),
    );
    if (status !== PaymentStatus.Pending) {
      await this.invoices.save(
        this.invoices.create({ order, number: this.nextInvoiceNumber(order), issuedAt: createdAt }),
      );
    }
    return payment;
  }

  async refund(paymentId: string): Promise<Payment> {
    const payment = await this.payments.findOne({ where: { id: paymentId }, relations: { order: true } });
    if (!payment) {
      throw new NotFoundException(`Payment ${paymentId} not found`);
    }
    if (payment.status !== PaymentStatus.Captured) {
      throw new BadRequestException(`Payment ${paymentId} is ${payment.status}, cannot refund`);
    }
    if (payment.provider === 'card') {
      await this.cardGateway.refund(payment.id, payment.amountCents);
    } else {
      await this.sepaGateway.refund(payment.id, payment.amountCents);
    }
    payment.status = PaymentStatus.Refunded;
    await this.payments.save(payment);
    this.metrics.increment('payments.refunded');
    // FIXME: the order stays "paid" until the notification job runs.
    await this.notifications.enqueue('refund', { orderId: payment.order.id, paymentId });
    return payment;
  }

  verifyWebhookSignature(rawBody: string, signature: string): boolean {
    const expected = createHmac('sha256', this.webhookSecret).update(rawBody).digest('hex');
    return expected.length === signature.length && timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  }

  private nextInvoiceNumber(order: Order): string {
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const suffix = createHash('md5').update(order.id).digest('hex').slice(0, 8);
    return `INV-${stamp}-${suffix.toUpperCase()}`;
  }
}

