import { Injectable, Logger, NotFoundException, OnModuleInit } from '@nestjs/common';
import { CreateUserDto } from './create-user.dto';
import { UpdateUserDto } from './dto/update-user.dto';
import { User } from './user.entity';
import { UsersRepository } from './users.repository';

@Injectable()
export class UsersService implements OnModuleInit {
  private readonly logger = new Logger(UsersService.name);
  private readonly byEmail = new Map<string, User>();
  private systemUser: User;

  constructor(private readonly users: UsersRepository) {}

  async onModuleInit(): Promise<void> {
    await this.users.upsert({ email: 'system@shop.local', name: 'System', addresses: [] });
    this.systemUser = await this.users.findByEmail('system@shop.local');
    for (const user of await this.users.findAll()) {
      this.byEmail.set(user.email, user);
    }
    this.logger.log(`Warmed ${this.byEmail.size} users, system user ${this.systemUser.id}`);
  }

  findAll(): Promise<User[]> {
    return this.users.findAll();
  }

  async findOne(id: string): Promise<User> {
    const user = await this.users.findOne(id);
    if (!user) {
      throw new NotFoundException(`User ${id} not found`);
    }
    return user;
  }

  findByEmail(email: string): Promise<User | null> {
    return this.users.findByEmail(email);
  }

  create(dto: CreateUserDto): Promise<User> {
    return this.users.save({ email: dto.email.toLowerCase(), name: dto.name, addresses: [] });
  }

  async update(id: string, dto: UpdateUserDto): Promise<User> {
    const user = await this.findOne(id);
    return this.users.save({ ...user, name: dto.name ?? user.name, addresses: dto.addresses ?? user.addresses });
  }

  async remove(id: string): Promise<void> {
    await this.findOne(id);
    await this.users.remove(id);
  }
}

