import 'reflect-metadata';
import { writeFileSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { Logger } from '@nestjs/common';
import { NestFactory, SerializedGraph } from '@nestjs/core';
import { WorkerModule } from './worker.module';

const traceEnabled = process.env.NEST_BOOT_TRACE === '1';
const hookTimings: { className: string; hook: string; ms: number; startMs: number }[] = [];

async function bootstrap() {
  const t0 = performance.now();
  const app = await NestFactory.createApplicationContext(WorkerModule, {
    snapshot: traceEnabled,
    instrument: traceEnabled
      ? {
          instanceDecorator(instance: any) {
            if (!instance || typeof instance !== 'object') return instance;
            for (const hook of ['onModuleInit', 'onApplicationBootstrap']) {
              const original = instance[hook];
              if (typeof original !== 'function') continue;
              try {
                instance[hook] = async function (...args: unknown[]) {
                  const start = performance.now();
                  try {
                    return await original.apply(this, args);
                  } finally {
                    hookTimings.push({
                      className: this.constructor.name,
                      hook,
                      ms: performance.now() - start,
                      startMs: start - t0,
                    });
                  }
                };
              } catch {} // frozen instances stay untimed
            }
            return instance;
          },
        }
      : undefined,
  });
  app.enableShutdownHooks();
  const startupMs = performance.now() - t0;
  Logger.log('Worker started, waiting for jobs', 'Bootstrap');

  if (traceEnabled) {
    const graph = JSON.parse(app.get(SerializedGraph).toString());
    Object.assign(graph, { startupMs, hookTimings });
    writeFileSync('worker-timings.json', JSON.stringify(graph));
    Logger.log(`Boot trace written to worker-timings.json (${startupMs.toFixed(0)}ms)`, 'Bootstrap');
  }
}

bootstrap().catch((err) => {
  console.error('Worker failed to start', err);
  process.exit(1);
});

